// Runs once per ministry (inside the loop).
// Turns the scraper response into one item per article, with source_id and
// n8n_content_hash taken from here - never from the AI model.
const crypto = require('crypto');

function normalizeWhitespace(s) {
  return String(s ?? '').replace(/\s+/g, ' ').trim();
}

function canonicalUrl(url) {
  const raw = String(url ?? '').trim();
  if (!raw) return raw;
  try {
    const u = new URL(raw);
    const drop = new Set([
      'utm_source','utm_medium','utm_campaign','utm_term','utm_content',
      'at_medium','at_campaign','at_custom1','at_custom2','at_custom3',
      'fbclid','gclid','igshid','mc_cid','mc_eid'
    ]);
    for (const k of [...u.searchParams.keys()]) {
      if (drop.has(k.toLowerCase())) u.searchParams.delete(k);
    }
    const params = [...u.searchParams.entries()].sort(([a], [b]) => a.localeCompare(b));
    u.search = '';
    for (const [k, v] of params) u.searchParams.append(k, v);
    u.pathname = u.pathname.replace(/\/+$/, '');
    return u.toString();
  } catch {
    return raw;
  }
}

function sha256Hex(input) {
  return crypto.createHash('sha256').update(input, 'utf8').digest('hex');
}

const target = $('Loop Over Ministries').first().json;
const res = $input.first().json || {};
const data = Array.isArray(res.data) ? res.data : [];

const articles = data
  .filter(a => a && a.link && a.title)
  .map(a => {
    const source_id = target.source_id;
    // Same hash material as the original workflow
    const hashMaterial = [
      'v1',
      source_id,
      canonicalUrl(a.link),
      normalizeWhitespace(a.title).toLowerCase(),
      normalizeWhitespace(a.content).toLowerCase()
    ].join('|');

    return {
      json: {
        source_id,
        source_name: target.name_en,
        scraper_key: target.scraper_key,
        title: a.title,
        content: a.content || '',
        link: a.link,
        published_date: a.date_iso || null,
        raw_date: a.date || null,
        n8n_content_hash: sha256Hex(hashMaterial)
      }
    };
  });

// Always return at least one item, otherwise the loop stops early.
if (articles.length === 0) {
  return [{
    json: {
      __empty: true,
      scraper_key: target.scraper_key,
      scrape_status: res.status || 'error',
      scrape_message: res.message || res.error || null
    }
  }];
}
return articles;

// All ministries done. Drop empty markers and repeated URLs within this run.
const seen = new Set();
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  if (j.__empty) {
    console.log(`[${j.scraper_key}] no articles (${j.scrape_status}: ${j.scrape_message ?? ''})`);
    continue;
  }
  if (seen.has(j.link)) continue;
  seen.add(j.link);
  out.push({ json: j });
}
return out;

// Earliest start date across all ministries = oldest article date we could have re-scraped.
const starts = $('Get Scrape Targets').all().map(i => i.json.start_date).filter(Boolean).sort();
return [{ json: { since: starts[0] } }];

// Keep only articles whose URL is not already in the articles table.
// Input: rows {source_url} already stored in Supabase since the earliest start date.
const existing = new Set();
for (const item of $input.all()) {
  const r = item.json;
  if (!r || Object.keys(r).length === 0) continue;          // empty result
  if (typeof r === 'string') { existing.add(r); continue; }
  const url = r.url ?? r.source_url ?? r.p_url ?? r.article_url;
  if (!url) continue;
  if (r.url_exists === undefined || r.url_exists === true) existing.add(url);
}

const all = $('Dedupe In Run').all();
const fresh = all.filter(i => !existing.has(i.json.link));
console.log(`scraped ${all.length}, already in Supabase ${all.length - fresh.length}, new ${fresh.length}`);
return fresh.map(i => ({ json: i.json }));
